public abstract record Shape
{
    private Shape() { }                              // closes the hierarchy
    public sealed record Circle(double Radius) : Shape;
    public sealed record Rectangle(double W, double H) : Shape;
}

static double Area(Shape s) => s switch
{
    Shape.Circle c    => Math.PI * c.Radius * c.Radius,
    Shape.Rectangle r => r.W * r.H,
    // adding a variant without an arm is CS8509 -> error with warnings-as-errors
};
